<?php
/**
 * Date period iterator for events based on a timetable.
 *
 * Like DatePeriod, the iterator does NOT include the end date.
 *
 * @see       DatePeriod
 * @author    Amri Sannang <amri.sannang@alaress.com.au>
 * @copyright Copyright 2014, Alaress Pty Ltd
 * @link      http://www.alaress.com.au/
 */

use \Schoolbox\Campus;

class External_TimetableDatePeriod implements Iterator {

    /**
     * @var DateTime
     */
    protected $start;

    /**
     * @var DateTime
     */
    protected $end;

    /**
     * @var Datetime
     */
    protected $current;

    /**
     * @var int
     */
    protected $index;

    /**
     * @var bool
     */
    protected $invert;

    /**
     * @var Campus
     */
    protected $campus;

    /**
     * @var External_Timetable
     */
    protected $externalTimetable;

    /**
     * @var int
     */
    protected $dayNumber;

    /**
     * Is the last date generated by this method valid? If not, valid() will
     * return false.
     *
     * @var bool
     */
    protected $isValid = true;

    /**
     * @param  DateTime           $start
     * @param  DateTime           $end
     * @param  External_Timetable $externalTimetable
     * @param  Campus                $campus
     * @throws InvalidArgumentException if $campus is not a valid campus
     * @throws InvalidArgumentException if $start does not have a timetable day
     */
    public function __construct(DateTime $start, DateTime $end, External_Timetable $externalTimetable, Campus $campus) {

        $this->start             = clone $start;
        $this->end               = clone $end;
        $this->externalTimetable = $externalTimetable;
        $this->campus            = $campus;

        // Deal exclusively in dates
        $this->start->setTime(0,0,0);
        $this->end->setTime(0,0,0);

        // Figure out the day that $start starts at
        $dayNumber = $externalTimetable->getDayNumber($campus, $this->start->getTimestamp());
        if ($dayNumber === false) {
            throw new InvalidArgumentException("Campus \"{$campus->getName()}\" does not exist");
        }
        if (!$dayNumber) {
            throw new InvalidArgumentException("Start date \"{$this->start->format('Y-m-d')}\" is not timetabled");
        }
        $this->dayNumber = $dayNumber;
    }

    /**
     * Return the current element
     *
     * @link http://php.net/manual/en/iterator.current.php
     * @return DateTime
     */
    public function current() {
        return $this->current;
    }

    /**
     * Move forward to next element
     *
     * @link http://php.net/manual/en/iterator.next.php
     * @return void
     */
    public function next() {
        $this->index++;
        try {
            if ($this->invert) {
                $this->current = $this->externalTimetable->getPreviousDateForDayNumber(
                    $this->campus,
                    $this->dayNumber,
                    $this->current->getTimestamp()
                );
            }
            else {
                $this->current = $this->externalTimetable->getNextDateForDayNumber(
                    $this->campus,
                    $this->dayNumber,
                    $this->current->modify('+1 day')->getTimestamp()
                );
            }
        } catch (RangeException $e) {
            $this->isValid = false;
        }
    }

    /**
     * Return the key of the current element
     *
     * @link http://php.net/manual/en/iterator.key.php
     * @return int
     */
    public function key() {
        return $this->index;
    }

    /**
     * Checks if current position is valid
     *
     * @link http://php.net/manual/en/iterator.valid.php
     * @return bool
     */
    public function valid() {
        if (!$this->isValid) {
            return false;
        }
        $comparison = strcmp($this->current->format('Ymd'), $this->end->format('Ymd'));
        return $this->invert ?
            $comparison > 0:
            $comparison < 0;
    }

    /**
     * Rewind the Iterator to the first element
     *
     * @link http://php.net/manual/en/iterator.rewind.php
     * @return void
     */
    public function rewind() {
        $this->index   = 0;
        $this->current = $this->start;
        $this->invert  = ($this->end < $this->start);
    }
}
